	/** 
	 * jumpstart the process by instantiating2 Facility
	 */
	protected void jumpStart() throws Throwable {
		LOGGER.info( "\n======== create instances to get the ball rolling  ======== ");

		facilityId = FacilityService.getFacilityInstance()
		.createFacility( generateNewCommand() )
		.get();

		// ---------------------------------------------
		// set up query subscriptions after the 1st create
		// ---------------------------------------------
		testingStep = "create";
		setUpQuerySubscriptions();

		FacilityService.getFacilityInstance()
				.createFacility( generateNewCommand() )
				.get();

	}

	/** 
	 * Set up query subscriptions
	 */
	protected void setUpQuerySubscriptions() throws Throwable {
		LOGGER.info( "\n======== Setting Up Query Subscriptions ======== ");
			
		try {            
			subscriber.facilitySubscribe().updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetAll update received for Facility : " + successValue.getFacilityId());
							  if (successValue.getFacilityId().equals(facilityId)) {
								  if (testingStep.equals("create")) {
									  testingStep = "update";
									  update();
								  } else if (testingStep.equals("delete")) {
									  testingStep = "complete";
									  state( getAll().size() == sizeOfFacilityList - 1 , "value not deleted from list");
									  LOGGER.info("**********************************************************");
									  LOGGER.info("Facility test completed successfully...");
									  LOGGER.info("**********************************************************\n");
								  }
							  }
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on facility consumed")
					);
			subscriber.facilitySubscribe( facilityId ).updates().subscribe(
					  successValue -> {
						  LOGGER.info(successValue.toString());
						  try {
							  LOGGER.info("GetOne update received for Facility : " + successValue.getFacilityId() + " in step " + testingStep);
							  testingStep = "delete";
							  sizeOfFacilityList = getAll().size();
							  delete();
						  } catch( Throwable exc ) {
							  LOGGER.warning( exc.getMessage() );
						  }
					  },
					  error -> LOGGER.warning(error.getMessage()),
					  () -> LOGGER.info("Subscription on facility for facilityId consumed")

					);
			

			}
			catch (Exception e) {
				LOGGER.warning( e.getMessage() );
				throw e;
			}
		}
		
		/** 
	 * read a Facility. 
	 */
	protected Facility read() throws Throwable {
		LOGGER.info( "\n======== READ ======== ");
		LOGGER.info( "-- Reading a previously created Facility" );

		Facility entity = null;
		StringBuilder msg = new StringBuilder( "-- Failed to read Facility with primary key" );
		msg.append( facilityId );
		
		FacilityFetchOneSummary fetchOneSummary = new FacilityFetchOneSummary( facilityId );

		try {
			entity = FacilityService.getFacilityInstance().getFacility( fetchOneSummary );

			assertNotNull( entity,msg.toString() );

			LOGGER.info( "-- Successfully found Facility " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return entity;
	}

	/** 
	 * updating a Facility.
	 */
	protected void update() throws Throwable {
		LOGGER.info( "\n======== UPDATE ======== ");
		LOGGER.info( "-- Attempting to update a Facility." );

		StringBuilder msg = new StringBuilder( "Failed to update a Facility : " );        
		Facility entity = read();
		UpdateFacilityCommand command = generateUpdateCommand();
		command.setFacilityId(entity.getFacilityId());

		try {            
			assertNotNull( entity, msg.toString() );

			LOGGER.info( "-- Now updating the created Facility." );

			// for use later on...
			facilityId = entity.getFacilityId();

			FacilityService proxy = FacilityService.getFacilityInstance();  

			proxy.updateFacility( command ).get();

			LOGGER.info( "-- Successfully saved Facility - " + entity.toString() );
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : primarykey = " + facilityId + " : command -" +  command + " : " + e );

			throw e;
		}
	}

	/** 
	 * delete a Facility.
	 */
	protected void delete() throws Throwable {
		LOGGER.info( "\n======== DELETE ======== ");
		LOGGER.info( "-- Deleting a previously created Facility." );

		Facility entity = null;
		
		try{
		    entity = read(); 
			LOGGER.info( "-- Successfully read Facility with id " + facilityId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to read Facility with id " + facilityId );

			throw e;
		}

		try{
			FacilityService.getFacilityInstance().delete( new DeleteFacilityCommand( entity.getFacilityId() ) ).get();
			LOGGER.info( "-- Successfully deleted Facility with id " + facilityId );            
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( "-- Failed to delete Facility with id " + facilityId );

			throw e;
		}
	}

	/**
	 * get all Facilitys.
	 */
	protected List<Facility> getAll() throws Throwable {    
		LOGGER.info( "======== GETALL ======== ");
		LOGGER.info( "-- Retrieving Collection of Facilitys:" );

		StringBuilder msg = new StringBuilder( "-- Failed to get all Facility : " );        
		List<Facility> collection  = new ArrayList<>();

		try {
			// call the static get method on the FacilityService
			collection = FacilityService.getFacilityInstance().getAllFacility();
			assertNotNull( collection, "An Empty collection of Facility was incorrectly returned.");
			
			// Now print out the values
			Facility entity = null;            
			Iterator<Facility> iter = collection.iterator();
			int index = 1;

			while( iter.hasNext() ) {
				// Retrieve the entity   
				entity = iter.next();

				assertNotNull( entity,"-- null entity in Collection." );
				assertNotNull( entity.getFacilityId(), "-- entity in Collection has a null primary key" );        

				LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
				index++;
			}
		}
		catch ( Throwable e ) {
			LOGGER.warning( unexpectedErrorMsg );
			LOGGER.warning( msg.toString() + " : " + e );

			throw e;
		}
		
		return collection;			
	}

